// Brings PostgREST's own test fixtures and test requests into packages/rest/tests/compare/upstream/.
//
//   bun run sync:upstream                  # downloads the pinned source tarball
//   bun run sync:upstream --from ~/postgrest   # uses a checkout instead
//
// It writes two generated files, both committed, so the suite needs no network and is pinned to the
// same PostgREST the differential cases already compare against (the version comes from mise.toml):
//
//   upstream/fixture.sql   test/spec/fixtures/load.sql with its `\ir` includes inlined, verbatim
//                          otherwise -- 300-odd relations and 350-odd functions, 79 of them views
//   upstream/cases.ts      the requests of test/spec/Feature/**/*.hs that can be replayed as they
//                          are: anonymous, and from a block whose AppConfig we can match
//
// Their *expectations* are deliberately not harvested: the pinned binary is the expectation, which
// is what makes this a differential suite rather than a port of theirs.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const root = new URL("../", import.meta.url);
const outDir = new URL("packages/rest/tests/compare/upstream/", root);

/** The version of the binary the differential cases run against: fixtures and requests must match it. */
const version = (() => {
  const mise = readFileSync(new URL("mise.toml", root), "utf8");
  const m = /"github:PostgREST\/postgrest"\s*=\s*"([^"]+)"/.exec(mise);
  if (!m) throw new Error("mise.toml does not pin github:PostgREST/postgrest");
  return m[1]!;
})();

const fromArg = process.argv.indexOf("--from");
const source = await (async () => {
  if (fromArg !== -1) return process.argv[fromArg + 1]!;
  const dir = join(tmpdir(), `postgrest-src-${version}`);
  const inner = join(dir, `postgrest-${version}`);
  if (await Bun.file(join(inner, "test/spec/fixtures/load.sql")).exists()) return inner;
  mkdirSync(dir, { recursive: true });
  const url = `https://github.com/PostgREST/postgrest/archive/refs/tags/v${version}.tar.gz`;
  console.log(`downloading ${url}`);
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${url}: ${res.status}`);
  const tar = join(dir, "src.tar.gz");
  await Bun.write(tar, await res.arrayBuffer());
  const p = Bun.spawnSync(["tar", "-xzf", tar, "-C", dir]);
  if (p.exitCode !== 0) throw new Error(`tar: ${new TextDecoder().decode(p.stderr)}`);
  return inner;
})();

const read = (p: string) => readFileSync(join(source, p), "utf8");

// ── the fixture database ─────────────────────────────────────────────────────
// load.sql is psql: `\ir` includes, and one `\if` on orioledb. The includes are inlined here, in
// their order; orioledb is dropped (it is an alternative storage engine, not part of the API
// surface). What is left still carries two psql-isms -- `:DBNAME`, `:"PGUSER"` and two
// `COPY ... FROM STDIN` blocks -- which `upstream/load.ts` deals with at load time rather than here,
// so that this file stays comparable with upstream line by line.
const loadSql = read("test/spec/fixtures/load.sql");
const includes = [...loadSql.matchAll(/^\\ir\s+(\S+)\s*$/gm)].map((m) => m[1]!).filter((p) => !p.endsWith("orioledb.sql"));
if (includes.length < 7) throw new Error(`load.sql: only ${includes.length} includes found`);

const fixture = [
  `-- Generated by scripts/sync-upstream-fixture.ts from PostgREST v${version} -- do not edit.`,
  `-- test/spec/fixtures/load.sql, with its \\ir includes inlined in order (orioledb.sql dropped).`,
  `-- Loaded by packages/rest/tests/compare/upstream/load.ts, which substitutes the psql variables`,
  `-- (:DBNAME, :"PGUSER") and rewrites the COPY ... FROM STDIN blocks as INSERTs.`,
  "",
  ...includes.map((p) => {
    const rel = `test/spec/fixtures/${p.replace(/^\.\.\/\.\.\//, "")}`;
    const path = p.startsWith("../../") ? `test/${p.slice(6)}` : rel;
    return `-- ── ${path} ──\n${read(join("test/spec/fixtures", p))}`;
  }),
].join("\n");
mkdirSync(outDir, { recursive: true });
writeFileSync(new URL("fixture.sql", outDir), fixture);

// ── their requests ───────────────────────────────────────────────────────────
/**
 * Every spec is `withConfig <AppConfig> $ do ...`, and most of them modify `baseCfg`. A block whose
 * configuration we cannot reproduce cannot be replayed, so only these are kept: the bare `baseCfg`,
 * and the one override the harness already matches (aggregates, which this engine always allows and
 * the differential harness turns on in PostgREST).
 */
const ACCEPTED_OVERRIDES = new Set(["configDbAggregates = True"]);

/** `Network.HTTP.Types.Header` names, as used in the header tuples of the specs. */
const HEADER_IDENTS: Record<string, string> = {
  hAccept: "Accept",
  hAcceptLanguage: "Accept-Language",
  hAuthorization: "Authorization",
  hContentType: "Content-Type",
  hOrigin: "Origin",
  hPrefer: "Prefer",
  hRange: "Range",
};

type Headers = Array<[string, string]>;

/** A Haskell string literal, from its opening quote. Returns null for the escapes we do not read. */
const haskellString = (s: string, at: number): { value: string; end: number } | null => {
  if (s[at] !== '"') return null;
  let out = "";
  for (let i = at + 1; i < s.length; i++) {
    const c = s[i]!;
    if (c === '"') return { value: out, end: i + 1 };
    if (c === "\n") return null;
    if (c !== "\\") {
      out += c;
      continue;
    }
    const n = s[++i];
    if (n === "n") out += "\n";
    else if (n === "t") out += "\t";
    else if (n === "r") out += "\r";
    else if (n === '"' || n === "\\" || n === "'") out += n;
    else return null; // a string gap, a numeric escape: not worth reading
  }
  return null;
};

/** Skip whitespace, Haskell comments and the `$` of `f $ x`. */
const skipGap = (s: string, at: number): number => {
  for (let i = at; i < s.length; ) {
    const c = s[i]!;
    if (c === " " || c === "\n" || c === "\r" || c === "\t") i++;
    else if (s.startsWith("--", i)) i = s.indexOf("\n", i) === -1 ? s.length : s.indexOf("\n", i);
    else return i;
  }
  return s.length;
};

/**
 * A header list: `[]`, `mempty`, a list of tuples, or one of the helpers SpecHelper (and a couple of
 * `where` clauses) defines. Anything else is left alone -- the request is then not harvested.
 */
const headerExpr = (s: string, at: number, locals: Map<string, Headers>): { value: Headers; end: number } | null => {
  let i = skipGap(s, at);
  if (s.startsWith("mempty", i)) return { value: [], end: i + 6 };
  if (s.startsWith("planHdr", i)) return { value: [["Accept", "application/vnd.pgrst.plan+json"]], end: i + 7 };

  // `(acceptHdrs "text/csv")`, `(rangeHdrs $ ByteRangeFromTo 0 1)`, and the `where`-bound aliases
  const call = /^\(?\s*([a-zA-Z][A-Za-z0-9_']*)\s*(?:\$\s*)?/.exec(s.slice(i));
  if (call) {
    const paren = s[i] === "(";
    const name = call[1]!;
    let j = i + call[0].length;
    if (name === "acceptHdrs") {
      const str = haskellString(s, skipGap(s, j));
      if (!str) return null;
      j = str.end;
      if (paren) {
        j = skipGap(s, j);
        if (s[j] !== ")") return null;
        j++;
      }
      return { value: [["Accept", str.value]], end: j };
    }
    if (name === "rangeHdrs") {
      const r = /^\s*(ByteRangeFromTo\s+(\d+)\s+(\d+)|ByteRangeFrom\s+(\d+)|ByteRangeSuffix\s+(\d+))\s*/.exec(s.slice(j));
      if (!r) return null;
      j += r[0].length;
      if (paren) {
        if (s[j] !== ")") return null;
        j++;
      }
      const range = r[2] !== undefined ? `${r[2]}-${r[3]}` : r[4] !== undefined ? `${r[4]}-` : `-${r[5]}`;
      return { value: [["Range-Unit", "items"], ["Range", range]], end: j };
    }
    if (!paren && locals.has(name)) return { value: locals.get(name)!, end: i + name.length };
    if (!paren && HEADER_IDENTS[name] === undefined && name !== "mempty") return null;
  }

  if (s[i] !== "[") return null;
  const value: Headers = [];
  i++;
  for (;;) {
    i = skipGap(s, i);
    if (s[i] === "]") return { value, end: i + 1 };
    if (s[i] !== "(") return null;
    i = skipGap(s, i + 1);
    let name: string;
    const lit = haskellString(s, i);
    if (lit) {
      name = lit.value;
      i = lit.end;
    } else {
      const id = /^([a-zA-Z][A-Za-z0-9_']*)/.exec(s.slice(i));
      if (!id || HEADER_IDENTS[id[1]!] === undefined) return null;
      name = HEADER_IDENTS[id[1]!]!;
      i += id[0].length;
    }
    i = skipGap(s, i);
    // `("Range-Unit" :: CI BS.ByteString, "items")`
    if (s.startsWith("::", i)) {
      const comma = s.indexOf(",", i);
      if (comma === -1) return null;
      i = comma;
    }
    if (s[i] !== ",") return null;
    i = skipGap(s, i + 1);
    const v = haskellString(s, i);
    if (!v) return null;
    i = skipGap(s, v.end);
    if (s[i] !== ")") return null;
    i = skipGap(s, i + 1);
    value.push([name, v.value]);
    if (s[i] === ",") i++;
    else if (s[i] !== "]") return null;
  }
};

/** A request body: a string literal, a `[json| ... |]` quasi-quote, or `mempty`. */
const bodyExpr = (s: string, at: number): { value: string; end: number } | null => {
  const i = skipGap(s, at);
  if (s.startsWith("mempty", i)) return { value: "", end: i + 6 };
  if (s.startsWith("[json|", i)) {
    const close = s.indexOf("|]", i);
    if (close === -1) return null;
    return { value: s.slice(i + 6, close).trim(), end: close + 2 };
  }
  const str = haskellString(s, i);
  return str ? { value: str.value, end: str.end } : null;
};

/**
 * The `AppConfig` argument of a `withConfig` call: everything up to the `$` that applies it, with
 * brackets and string literals balanced -- `baseCfg{configDbPreRequest = Just $ ...}` carries a `$`
 * of its own inside the braces.
 */
const configExpr = (s: string, at: number): string => {
  let depth = 0;
  for (let i = skipGap(s, at); i < s.length; i++) {
    const c = s[i]!;
    if (c === '"') {
      const str = haskellString(s, i);
      i = str ? str.end - 1 : s.length;
    } else if (c === "(" || c === "{" || c === "[") depth++;
    else if (c === ")" || c === "}" || c === "]") depth--;
    else if (depth === 0 && (c === "$" || c === "\n")) return s.slice(at, i);
  }
  return s.slice(at);
};

export interface Harvested {
  name: string;
  method: string;
  path: string;
  headers?: Record<string, string>;
  body?: string;
  source: string;
}

const specFiles = [...new Bun.Glob("test/spec/Feature/**/*.hs").scanSync(source)].sort();
const harvested = new Map<string, Harvested>();
const skipped = new Map<string, number>();
const note = (why: string) => skipped.set(why, (skipped.get(why) ?? 0) + 1);

for (const file of specFiles) {
  const text = read(file);

  // The regions of the file whose AppConfig we can reproduce. `withConfig <cfg> $` starts one, and
  // it runs to the next `withConfig` (a few files hold several specs, with a different config each).
  const regions: Array<[number, number]> = [];
  // `spec withConfig = withConfig baseCfg $ do ...`: the binder is not a call, skip it.
  const starts = [...text.matchAll(/withConfig\s*/g)].filter((m) => {
    const rest = text.slice(m.index + m[0].length);
    return !rest.startsWith("=") && !rest.startsWith("::");
  });
  for (const [n, m] of starts.entries()) {
    const from = m.index + m[0].length;
    const to = starts[n + 1]?.index ?? text.length;
    const cfg = configExpr(text, from);
    const overrides = /baseCfg\s*\{([^}]*)\}/.exec(cfg);
    const bare = /^\(?\s*baseCfg\s*\)?\s*$/.test(cfg);
    if (bare) regions.push([from, to]);
    else if (
      overrides &&
      overrides[1]!
        .split(",")
        .map((o) => o.trim())
        .every((o) => ACCEPTED_OVERRIDES.has(o))
    ) {
      regions.push([from, to]);
    } else note(`config: ${cfg.replace(/\s+/g, " ").trim().slice(0, 60)}`);
    if (regions.at(-1)?.[0] === from && process.env["VERBOSE"]) {
      console.log(`  ${file.replace("test/spec/", "")}: ${cfg.replace(/\s+/g, " ").trim()}`);
    }
  }
  if (regions.length === 0) continue;
  const inRegion = (i: number) => regions.some(([a, b]) => i >= a && i < b);

  // `where`-bound header aliases, e.g. `firefoxAcceptHdrs = acceptHdrs "text/html,..."`
  const locals = new Map<string, Headers>();
  for (const m of text.matchAll(/^\s*([a-z][A-Za-z0-9_']*)\s*=\s*(acceptHdrs\s)/gm)) {
    const h = headerExpr(text, m.index + m[0].length - m[2]!.length, locals);
    if (h) locals.set(m[1]!, h.value);
  }

  const verbs = /(?<![\w'])(get|post|put|patch|delete|request)\s/g;
  for (const m of text.matchAll(verbs)) {
    if (!inRegion(m.index)) continue;
    let i = m.index + m[0].length;
    let method: string;
    let headers: Headers = [];
    if (m[1] === "request") {
      const mm = /^\s*method([A-Z][a-z]+)\s/.exec(text.slice(i));
      if (!mm) continue; // `request` used as a value, not as a call
      method = mm[1]!.toUpperCase();
      i += mm[0].length;
    } else {
      method = m[1]!.toUpperCase();
    }
    const path = haskellString(text, skipGap(text, i));
    if (!path || !path.value.startsWith("/")) continue;
    i = path.end;
    if (m[1] === "request") {
      const h = headerExpr(text, i, locals);
      if (!h) {
        note(`headers: ${text.slice(i, i + 48).replace(/\s+/g, " ").trim()}`);
        continue;
      }
      // The specs often spell one header twice -- `[("Prefer", "return=representation"), ("Prefer",
      // "resolution=merge-duplicates")]` -- which HTTP reads as one comma-joined value. Merging
      // them here keeps that, and keeps the `tx=rollback` below from landing on the copy that a
      // later one would then drop.
      headers = [];
      for (const [k, v] of h.value) {
        const seen = headers.find(([n]) => n.toLowerCase() === k.toLowerCase());
        if (seen) seen[1] = `${seen[1]}, ${v}`;
        else headers.push([k, v]);
      }
      i = h.end;
    }
    let body: string | undefined;
    if (m[1] === "request" || method === "POST" || method === "PUT" || method === "PATCH") {
      const b = bodyExpr(text, i);
      if (!b) {
        note(`body: ${text.slice(i, i + 48).replace(/\s+/g, " ").trim()}`);
        continue;
      }
      // An empty body is only a case of its own where a body is expected: `post "/simple_pk" ""`
      // asks for PGRST102. Elsewhere (`request methodGet "/x" [] ""`) it is how the DSL spells
      // "no body", and `fetch` refuses to send one on a GET.
      if (b.value !== "" || method === "POST" || method === "PUT" || method === "PATCH") body = b.value;
    }

    const line = text.slice(0, m.index).split("\n").length;
    const where = `${file.replace("test/spec/", "")}:${line}`;

    if (headers.some(([k]) => k.toLowerCase() === "authorization")) {
      note("needs a JWT");
      continue;
    }
    const prefer = headers.find(([k]) => k.toLowerCase() === "prefer");
    if (method !== "GET" && method !== "HEAD" && method !== "OPTIONS") {
      // A write has to be rolled back: these all run on one shared fixture database, and their
      // order is not a fixture. `tx=rollback` is honoured by both engines (PostgREST with
      // `db-tx-end=commit-allow-override`, which the harness sets). A case that asks for a
      // transaction end of its own would have to be let through as it is, so it is left out.
      if (prefer && /\btx\s*=/.test(prefer[1])) {
        note("asks for a transaction end of its own");
        continue;
      }
      if (prefer) prefer[1] = `${prefer[1]}, tx=rollback`;
      else headers.push(["Prefer", "tx=rollback"]);
    }

    const hdrs = Object.fromEntries(headers);
    const name = `${method} ${path.value}` +
      (headers.length > 0 ? ` +${JSON.stringify(hdrs)}` : "") +
      (body !== undefined ? ` <${body.replace(/\s+/g, " ")}>` : "");
    if (!harvested.has(name)) {
      harvested.set(name, {
        name,
        method,
        path: path.value,
        ...(headers.length > 0 ? { headers: hdrs } : {}),
        ...(body !== undefined ? { body } : {}),
        source: where,
      });
    }
  }
}

const cases = [...harvested.values()].sort((a, b) => a.name.localeCompare(b.name));
const byMethod = new Map<string, number>();
for (const c of cases) byMethod.set(c.method, (byMethod.get(c.method) ?? 0) + 1);

writeFileSync(
  new URL("cases.ts", outDir),
  `// Generated by scripts/sync-upstream-fixture.ts from PostgREST v${version} -- do not edit.
//
// The requests of PostgREST's own \`test/spec/Feature/**/*.hs\`, harvested from the hspec-wai DSL:
// every one whose block runs on an AppConfig this harness reproduces, whose headers and body are
// literal enough to read without a Haskell compiler, and that needs no JWT. Their expectations are
// not here on purpose -- the pinned binary is the expectation (see \`../upstream.test.ts\`).
//
// Writes carry \`Prefer: tx=rollback\`, added here: one fixture database serves every case, and a
// case that changed it would decide what the next one sees.
//
// ${cases.length} cases: ${[...byMethod].sort().map(([k, v]) => `${v} ${k}`).join(", ")}.
export interface UpstreamCase {
  /** Identifies the request: method, path, and the headers and body when it has them. */
  readonly name: string;
  readonly method: string;
  readonly path: string;
  readonly headers?: Record<string, string>;
  /** Sent as-is, without a \`Content-Type\` unless the case carries one -- as upstream sends it. */
  readonly body?: string;
  /** Where it comes from, \`<spec file>:<line>\`. */
  readonly source: string;
}

// One line per case, so that a diff of this file reads as the requests that came and went.
export const upstreamCases: readonly UpstreamCase[] = [
${cases.map((c) => `  ${JSON.stringify(c)},`).join("\n")}
];
`,
);

console.log(`\nfixture.sql: ${fixture.split("\n").length} lines from ${includes.length} files`);
console.log(`cases.ts:    ${cases.length} cases (${[...byMethod].sort().map(([k, v]) => `${v} ${k}`).join(", ")})`);
console.log(`\nnot harvested:`);
for (const [why, n] of [...skipped].sort((a, b) => b[1] - a[1]).slice(0, 25)) {
  console.log(`  ${String(n).padStart(4)}  ${why}`);
}
